INSERT INTO amenity_editorial (amenity_id, tenant_id, short_name, short_description, long_description, active) VALUES ('6ad656569d1756c3fbef5564', 'urban-cowboy', 'Pendleton Blankets', 'Pendleton has been weaving wool in the Pacific Northwest for generations, with patterns that have become part of the visual language of the American outdoors', 'Pendleton has been weaving wool in the Pacific Northwest for generations, with patterns that have become part of the visual language of the American outdoors. Their blankets bring warmth, texture and a familiar bit of Americana into Cowboy''s very particular version of the Catskills. Pendleton still operates woolen mills in Oregon and Washington.', 1) ON CONFLICT DO NOTHING;
