INSERT INTO room_types (id, tenant_id, location_id, mews_room_category_id, name, slug, sort_order) VALUES ('6abd4a24eea80f91a64d01d1', 'urban-cowboy', '6abc9142d98b325b2821ca23', 'd68e4504-7944-43a7-8e12-b1f1012d6350', 'Slide Mountain Haus', 'slide-mountain-haus-full-haus', 17) ON CONFLICT (id) DO UPDATE SET tenant_id = excluded.tenant_id, location_id = excluded.location_id, mews_room_category_id = excluded.mews_room_category_id, name = excluded.name, slug = excluded.slug, sort_order = excluded.sort_order;
INSERT INTO room_types (id, tenant_id, location_id, mews_room_category_id, name, slug, sort_order) VALUES ('6abd4a24b799b47be46fb0e7', 'urban-cowboy', '6abc9142d98b325b2821ca23', 'd0961acc-145f-4ad9-a965-b1f1012e7f00', 'Slide Mountain Haus 2 Bedroom Suite', 'slide-mountain-haus-2-bedroom', 16) ON CONFLICT (id) DO UPDATE SET tenant_id = excluded.tenant_id, location_id = excluded.location_id, mews_room_category_id = excluded.mews_room_category_id, name = excluded.name, slug = excluded.slug, sort_order = excluded.sort_order;
INSERT INTO room_types (id, tenant_id, location_id, mews_room_category_id, name, slug, sort_order) VALUES ('6abd4a23f555b2ce3cc49edc', 'urban-cowboy', '6abc9142d98b325b2821ca23', '1c035d90-e174-4af4-95a1-b1f1012ed296', 'Slide Mountain Haus Double Queen', 'slide-mountain-haus-double-queen', 15) ON CONFLICT (id) DO UPDATE SET tenant_id = excluded.tenant_id, location_id = excluded.location_id, mews_room_category_id = excluded.mews_room_category_id, name = excluded.name, slug = excluded.slug, sort_order = excluded.sort_order;
INSERT INTO room_types (id, tenant_id, location_id, mews_room_category_id, name, slug, sort_order) VALUES ('6abd4a22b6febadd9de10f2b', 'urban-cowboy', '6abc9142d98b325b2821ca23', 'ea80fc33-3aa0-4a90-88db-b10600706caf', 'Lodge King', 'lodge-king', 9) ON CONFLICT (id) DO UPDATE SET tenant_id = excluded.tenant_id, location_id = excluded.location_id, mews_room_category_id = excluded.mews_room_category_id, name = excluded.name, slug = excluded.slug, sort_order = excluded.sort_order;
