INSERT INTO add_ons (id, tenant_id, location_id, name, description, mews_product_id, icon_media_asset_id, quantity_cap, sort_order, status) VALUES ('6ac372620a9fc691657ebf1e', 'urban-cowboy', NULL, 'Chocolate Truffles', 'A little taste of the Catskills waiting in your room. Six handpicked assorted chocolate truffles, perfect for arrival, after dinner, or whenever the mood strikes.', '41f8b399-a303-40ac-bbfc-b124016e6b85', NULL, 2, 1, 'published') ON CONFLICT (id) DO UPDATE SET tenant_id = excluded.tenant_id, location_id = excluded.location_id, name = excluded.name, description = excluded.description, mews_product_id = excluded.mews_product_id, icon_media_asset_id = excluded.icon_media_asset_id, quantity_cap = excluded.quantity_cap, sort_order = excluded.sort_order, status = excluded.status;
