INSERT INTO add_ons (id, tenant_id, location_id, name, description, mews_product_id, icon_media_asset_id, quantity_cap, sort_order, status) VALUES ('6ac3659626a0b23fca4ba4cc', 'urban-cowboy', NULL, 'Alice Mushroom Chocolate', 'Whether you need to refocus your morning with a burst of brain energy, or need to calm your mind at the end of a long day, Alice Mushroom Chocolate has the answer for you.', 'cad13cb9-752d-49e8-b5d3-b124016d3aa8', NULL, 4, 5, 'published') ON CONFLICT (id) DO UPDATE SET tenant_id = excluded.tenant_id, location_id = excluded.location_id, name = excluded.name, description = excluded.description, mews_product_id = excluded.mews_product_id, icon_media_asset_id = excluded.icon_media_asset_id, quantity_cap = excluded.quantity_cap, sort_order = excluded.sort_order, status = excluded.status;
INSERT INTO add_ons (id, tenant_id, location_id, name, description, mews_product_id, icon_media_asset_id, quantity_cap, sort_order, status) VALUES ('6ac3658035f8231d963596d4', 'urban-cowboy', NULL, 'Fresh Cut Flowers', 'Bring a little of the Catskills inside. We’ll have a fresh bouquet waiting in your room when you arrive.', 'd8009b60-0580-49e7-a5dd-b12401713848', NULL, 2, 3, 'published') ON CONFLICT (id) DO UPDATE SET tenant_id = excluded.tenant_id, location_id = excluded.location_id, name = excluded.name, description = excluded.description, mews_product_id = excluded.mews_product_id, icon_media_asset_id = excluded.icon_media_asset_id, quantity_cap = excluded.quantity_cap, sort_order = excluded.sort_order, status = excluded.status;
INSERT INTO add_ons (id, tenant_id, location_id, name, description, mews_product_id, icon_media_asset_id, quantity_cap, sort_order, status) VALUES ('6ac3657002f7d9d8f917db42', 'urban-cowboy', NULL, 'Celebration Cake', 'Mark a birthday, anniversary, or just a very good reason to get away with something sweet waiting in your room. We’ll have a celebration cake ready for your arrival, sourced from one of our favorite local bakers.', 'cad13cb9-752d-49e8-b5d3-b124016d3aa8', NULL, 1, 7, 'published') ON CONFLICT (id) DO UPDATE SET tenant_id = excluded.tenant_id, location_id = excluded.location_id, name = excluded.name, description = excluded.description, mews_product_id = excluded.mews_product_id, icon_media_asset_id = excluded.icon_media_asset_id, quantity_cap = excluded.quantity_cap, sort_order = excluded.sort_order, status = excluded.status;
INSERT INTO add_ons (id, tenant_id, location_id, name, description, mews_product_id, icon_media_asset_id, quantity_cap, sort_order, status) VALUES ('6ac3655da17f672b4dd9a313', 'urban-cowboy', NULL, 'Bathing Ritual Kit', 'Make the tub part of the plan. Your bathing ritual kit includes a few simple things to slow things down, like bath soak, a face mask, herbal tea, and a little something for afterward. Run the water. Put the robe on. The rest can wait.', 'cad13cb9-752d-49e8-b5d3-b124016d3aa8', NULL, 2, 6, 'published') ON CONFLICT (id) DO UPDATE SET tenant_id = excluded.tenant_id, location_id = excluded.location_id, name = excluded.name, description = excluded.description, mews_product_id = excluded.mews_product_id, icon_media_asset_id = excluded.icon_media_asset_id, quantity_cap = excluded.quantity_cap, sort_order = excluded.sort_order, status = excluded.status;
INSERT INTO add_ons (id, tenant_id, location_id, name, description, mews_product_id, icon_media_asset_id, quantity_cap, sort_order, status) VALUES ('6ac3654226a0b23fca4b8e6d', 'urban-cowboy', NULL, 'Smores Kit', 'Meet at the fire. Everything you need for a proper Cowboy s’more, packed and ready for the fire. Graham crackers, marshmallows, chocolate, and skewers included. All that’s missing is a little smoke in your hair.', 'cad13cb9-752d-49e8-b5d3-b124016d3aa8', NULL, 999, 9, 'published') ON CONFLICT (id) DO UPDATE SET tenant_id = excluded.tenant_id, location_id = excluded.location_id, name = excluded.name, description = excluded.description, mews_product_id = excluded.mews_product_id, icon_media_asset_id = excluded.icon_media_asset_id, quantity_cap = excluded.quantity_cap, sort_order = excluded.sort_order, status = excluded.status;
