INSERT INTO add_ons (id, tenant_id, location_id, name, description, mews_product_id, icon_media_asset_id, quantity_cap, sort_order, status) VALUES ('6ac3646a2435ff11b5014e5f', 'urban-cowboy', NULL, 'Dog Inclusion', 'Bring the dog. We love meeting them. A $50 per dog, per night cleaning fee applies. Dogs only, please. If you forgot potty bags, food, or treats, swing by the Front Desk. Chances are the team was already hoping to meet your pup anyway.', 'c74edf03-043c-4217-adbd-b124016a55ae', NULL, 2, 4, 'published') ON CONFLICT (id) DO UPDATE SET tenant_id = excluded.tenant_id, location_id = excluded.location_id, name = excluded.name, description = excluded.description, mews_product_id = excluded.mews_product_id, icon_media_asset_id = excluded.icon_media_asset_id, quantity_cap = excluded.quantity_cap, sort_order = excluded.sort_order, status = excluded.status;
