INSERT INTO content_revisions (id, content_item_id, revision, payload_json, published_at, created_by) VALUES ('6abe20f0623a2c8dec7a8b87-r1', '6abe20f0623a2c8dec7a8b87', 1, '{"id":"6abe20f0623a2c8dec7a8b87","cmsLocaleId":"6abc810fd801e90511049ada","createdOn":"2026-10-01T08:59:28.878Z","lastUpdated":"2026-10-01T08:59:28.878Z","lastPublished":"2026-10-01T10:18:32.985Z","isArchived":"false","isDraft":"false","media-type":"0cc2358c65f7d7a5e131a074da55b2c7","caption":"Explore the Walden. 10 cabin style rooms, each unique. Whether you choose a Walden King, or a bathing suite featuring a Japanese cedar soaking tub, or a suite with a den, each room offers a private deck overlooking the mountains or forest.","instagram-url":"https://www.instagram.com/urbancowboylodge/p/DdRoO7flqVv/","shortcode":"DdRoO7flqVv","instagram-username":"urbancowboylodge","sort":"3","caption-rich-text":"<p>Explore the Walden. 10 cabin style rooms, each unique. Whether you choose a Walden King, or a bathing suite featuring a Japanese cedar soaking tub, or a suite with a den, each room offers a private deck overlooking the mountains or forest.</p>","name":"Instagram_03","slug":"instagram-03"}', '2026-10-01T10:18:32.985Z', 'webflow-cms-import') ON CONFLICT (id) DO UPDATE SET content_item_id = excluded.content_item_id, revision = excluded.revision, payload_json = excluded.payload_json, published_at = excluded.published_at, created_by = excluded.created_by;
INSERT INTO content_revisions (id, content_item_id, revision, payload_json, published_at, created_by) VALUES ('6abe20ef623a2c8dec7a8995-r1', '6abe20ef623a2c8dec7a8995', 1, '{"id":"6abe20ef623a2c8dec7a8995","cmsLocaleId":"6abc810fd801e90511049ada","createdOn":"2026-10-01T08:59:27.426Z","lastUpdated":"2026-10-01T08:59:27.426Z","lastPublished":"2026-10-01T10:18:32.985Z","isArchived":"false","isDraft":"false","media-type":"122890cf752803a5eea5239a02302bcd","caption":"If you could disappear for a weekend which are you choosing? City or mountains?\n\n#iloveny #catskills #fall #mountainviews","instagram-url":"https://www.instagram.com/urbancowboylodge/reel/DduSYGShMb7/","shortcode":"DduSYGShMb7","instagram-username":"urbancowboylodge","sort":"2","caption-rich-text":"<p>If you could disappear for a weekend which are you choosing? City or mountains?#iloveny #catskills #fall #mountainviews</p>","name":"Instagram_02","slug":"instagram-02"}', '2026-10-01T10:18:32.985Z', 'webflow-cms-import') ON CONFLICT (id) DO UPDATE SET content_item_id = excluded.content_item_id, revision = excluded.revision, payload_json = excluded.payload_json, published_at = excluded.published_at, created_by = excluded.created_by;
INSERT INTO content_revisions (id, content_item_id, revision, payload_json, published_at, created_by) VALUES ('6abe20ed981346a17658eb04-r1', '6abe20ed981346a17658eb04', 1, '{"id":"6abe20ed981346a17658eb04","cmsLocaleId":"6abc810fd801e90511049ada","createdOn":"2026-10-01T08:59:25.819Z","lastUpdated":"2026-10-01T08:59:25.819Z","lastPublished":"2026-10-01T10:18:32.985Z","isArchived":"false","isDraft":"false","media-type":"0cc2358c65f7d7a5e131a074da55b2c7","caption":"You deserve to experience fall in the Catskills. We’re offering 20% off your midweek stay when you book direct. Link to book is in our bio!\n\nYour morning view\n\nThe key to your getaway","instagram-url":"https://www.instagram.com/urbancowboylodge/p/DdjsDqWliKR/","shortcode":"DdjsDqWliKR","instagram-username":"urbancowboylodge","sort":"1","caption-rich-text":"<p>You deserve to experience fall in the Catskills. We’re offering 20% off your midweek stay when you book direct. Link to book is in our bio!Your morning viewThe key to your getaway</p>","name":"Instagram_01","slug":"instagram-01"}', '2026-10-01T10:18:32.985Z', 'webflow-cms-import') ON CONFLICT (id) DO UPDATE SET content_item_id = excluded.content_item_id, revision = excluded.revision, payload_json = excluded.payload_json, published_at = excluded.published_at, created_by = excluded.created_by;
INSERT INTO content_revisions (id, content_item_id, revision, payload_json, published_at, created_by) VALUES ('6abd3c4be1b90d342b55ec9b-r1', '6abd3c4be1b90d342b55ec9b', 1, '{"id":"6abd3c4be1b90d342b55ec9b","cmsLocaleId":"6abc810fd801e90511049ada","createdOn":"2026-09-30T16:43:55.424Z","lastUpdated":"2026-10-06T00:16:39.789Z","lastPublished":"2026-10-09T09:38:30.479Z","isArchived":"false","isDraft":"false","outlet-name":"Ralph’s Bar & Bowling","outlet-type":"4f8dbe9c0a99353279b971327c3790c3","street-address-line-1":"822 Oliverea Road","street-address-line-2":"","city":"Big Indian","state":"NY","postal-code":"12410","outlet-short-name":"Ralph’s Bar & Bowling","short-description":"Ralph’s Bar & Bowling is a Catskills time capsule with two old-school lanes, a full bar, pool table, dancing, and very little reason to call it an early night.","long-description":"Ralph’s Bar & Bowling is a Catskills time machine with two lanes of old-school bowling, a full bar, pool table, dancing, and plenty of reasons to stay awhile. Open to everyone, Ralph’s is the Lodge’s neighborhood hangout for Cowboy Cocktails, cold beer, hot dogs, brats, pretzels, and weekend pizza from Auggie’s Tiny Pizza Kitchen. No reservations. Just show up, grab a drink, and step back in time","website":"","instrgram":"","facebook":"","yelp":"","hours-of-operation":"Mon–Thu 3–9pm\nFri–Sun 3–11pm (Pizza: Thu–MON 3–9pm)","email-address":"","location":"6abc9142d98b325b2821ca23","reservations-url":"","main-phone":"(845) 254-5016","google-maps-link":"","name":"Ralph’s Bar & Bowling","slug":"ralphs-bar-bowling"}', '2026-10-09T09:38:30.479Z', 'webflow-cms-import') ON CONFLICT (id) DO UPDATE SET content_item_id = excluded.content_item_id, revision = excluded.revision, payload_json = excluded.payload_json, published_at = excluded.published_at, created_by = excluded.created_by;
INSERT INTO content_revisions (id, content_item_id, revision, payload_json, published_at, created_by) VALUES ('6abd3c05fea807987f2c8b7c-r1', '6abd3c05fea807987f2c8b7c', 1, '{"id":"6abd3c05fea807987f2c8b7c","cmsLocaleId":"6abc810fd801e90511049ada","createdOn":"2026-09-30T16:42:45.882Z","lastUpdated":"2026-10-03T23:05:33.820Z","lastPublished":"2026-10-03T23:52:28.374Z","isArchived":"false","isDraft":"false","outlet-name":"Parlor Bar","outlet-type":"4f8dbe9c0a99353279b971327c3790c3","street-address-line-1":"","street-address-line-2":"","city":"","state":"","postal-code":"","outlet-short-name":"Parlor Bar","short-description":"Every great lodge needs a good bar. The Parlor Bar is ours. Settle with great cocktails, a seasonal drink list, a fire nearby, and just enough swagger to keep the night from getting too civilized.","long-description":"Every great lodge needs a good bar. The Parlor Bar is ours. Settle in for some of the best cocktails around, a rotating drink menu inspired by the season, and casual service that makes you feel right at home. Settle in for a pre-dinner cocktail, a slow evening by the fire, or one more round before calling it a night.","website":"","instrgram":"","facebook":"","yelp":"","hours-of-operation":"Mon-Fri 3-10pm\nSat & Sun 1-10pm","email-address":"","location":"6abc9142d98b325b2821ca23","reservations-url":"","main-phone":"","google-maps-link":"","name":"Parlor Bar","slug":"parlor-bar"}', '2026-10-03T23:52:28.374Z', 'webflow-cms-import') ON CONFLICT (id) DO UPDATE SET content_item_id = excluded.content_item_id, revision = excluded.revision, payload_json = excluded.payload_json, published_at = excluded.published_at, created_by = excluded.created_by;
INSERT INTO content_revisions (id, content_item_id, revision, payload_json, published_at, created_by) VALUES ('6abd3b53ce8fc8aa2a71c282-r1', '6abd3b53ce8fc8aa2a71c282', 1, '{"id":"6abd3b53ce8fc8aa2a71c282","cmsLocaleId":"6abc810fd801e90511049ada","createdOn":"2026-09-30T16:39:47.139Z","lastUpdated":"2026-10-03T23:05:33.817Z","lastPublished":"2026-10-03T23:52:28.374Z","isArchived":"false","isDraft":"false","outlet-name":"The Dinning Room","outlet-type":"b263d2d5ddcea0f1e1e681efd9a6a35a","street-address-line-1":"","street-address-line-2":"","city":"","state":"","postal-code":"","outlet-short-name":"The Dinning Room","short-description":"Seasonal Catskills fare made with ingredients from local growers and makers, balancing familiar flavors with a little polish and just enough reason to linger over dinner.","long-description":"The Dining Room serves seasonal fare with ingredients sourced from local makers and growers. It’s thoughtful, familiar, and quietly elevated — the kind of meal that feels special without trying too hard. Reservations are recommended for The Dining Room.","website":"","instrgram":"","facebook":"","yelp":"","hours-of-operation":"Brunch: 8-11am daily\nDinner: 5-9pm daily","email-address":"","location":"6abc9142d98b325b2821ca23","reservations-url":"","main-phone":"","google-maps-link":"","name":"The Dining Room","slug":"the-dinning-room"}', '2026-10-03T23:52:28.374Z', 'webflow-cms-import') ON CONFLICT (id) DO UPDATE SET content_item_id = excluded.content_item_id, revision = excluded.revision, payload_json = excluded.payload_json, published_at = excluded.published_at, created_by = excluded.created_by;
